import '../../wallets/wallet/wallet.dart';
import '../../widgets/custom_buttons/app_bar_icon_button.dart';
import '../../widgets/icon_widgets/utxo_status_icon.dart';
import '../../widgets/rounded_container.dart';
import 'selectable_utxo_surface.dart';

class UtxoCard extends ConsumerStatefulWidget {
  const UtxoCard({
    super.key,
    required this.utxo,
    required this.walletId,
    required this.onSelectedChanged,
    required this.initialSelectedState,
    required this.canSelect,
    this.onOptionsPressed,
  });

  final String walletId;
  final UTXO utxo;
  final void Function(bool) onSelectedChanged;
  final bool initialSelectedState;
  final VoidCallback? onOptionsPressed;
  final bool canSelect;

  @override
  ConsumerState<UtxoCard> createState() => _UtxoCardState();
}

class _UtxoCardState extends ConsumerState<UtxoCard> {
  late Stream<UTXO?> stream;
  late UTXO utxo;

  late bool _selected;

  bool _isConfirmed(UTXO utxo, int currentChainHeight, Wallet wallet) {
    if (wallet is NamecoinWallet) {
      return wallet.checkUtxoConfirmed(utxo, currentChainHeight);
    } else {
      return utxo.isConfirmed(
        currentChainHeight,
        wallet.cryptoCurrency.minConfirms,
        wallet.cryptoCurrency.minCoinbaseConfirms,
      );
    }
  }

  @override
  void initState() {
    _selected = widget.initialSelectedState;
    utxo = widget.utxo;

    stream = MainDB.instance.watchUTXO(id: utxo.id);
    super.initState();
  }

  void _setSelected(bool selected) {
    if (_selected == selected) {
      return;
    }
    _selected = selected;
    widget.onSelectedChanged(_selected);
    setState(() {});
  }

  void _toggleSelected() => _setSelected(!_selected);

  @override
  void didUpdateWidget(covariant UtxoCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.initialSelectedState != widget.initialSelectedState) {
      _selected = widget.initialSelectedState;
    }
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType");

    final coin = ref.watch(pWalletCoin(widget.walletId));
    final currentHeight = ref.watch(pWalletChainHeight(widget.walletId));

    return SelectableUtxoSurface(
      canSelect: widget.canSelect,
      selected: _selected,
      onToggle: _toggleSelected,
      color: Theme.of(context).extension<StackColors>()!.popupBG,
      child: RoundedContainer(
        color: Theme.of(context).extension<StackColors>()!.popupBG,
        child: StreamBuilder<UTXO?>(
          stream: stream,
          builder: (context, snapshot) {
            if (snapshot.hasData) {
              utxo = snapshot.data!;
            }
            return Row(
              children: [
                UTXOStatusIcon(
                  blocked: utxo.isBlocked,
                  status:
                      _isConfirmed(
                        utxo,
                        currentHeight,
                        ref.watch(
                          pWallets.select((s) => s.getWallet(widget.walletId)),
                        ),
                      )
                      ? UTXOStatusIconStatus.confirmed
                      : UTXOStatusIconStatus.unconfirmed,
                  background: Theme.of(
                    context,
                  ).extension<StackColors>()!.popupBG,
                  selected: _selected,
                  width: 32,
                  height: 32,
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        ref
                            .watch(pAmountFormatter(coin))
                            .format(
                              utxo.value.toAmountAsRaw(
                                fractionDigits: coin.fractionDigits,
                              ),
                            ),
                        style: STextStyles.w600_14(context),
                      ),
                      const SizedBox(height: 2),
                      Row(
                        children: [
                          Flexible(
                            child: Text(
                              utxo.name.isNotEmpty
                                  ? utxo.name
                                  : utxo.address ?? utxo.txid,
                              style: STextStyles.w500_12(context).copyWith(
                                color: Theme.of(
                                  context,
                                ).extension<StackColors>()!.textSubtitle1,
                              ),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
                if (widget.onOptionsPressed != null) const SizedBox(width: 10),
                if (widget.onOptionsPressed != null)
                  AppBarIconButton(
                    semanticsLabel: "Output options",
                    tooltip: "Output options",
                    size: 36,
                    shadows: const [],
                    color: Theme.of(context).extension<StackColors>()!.popupBG,
                    icon: SvgPicture.asset(
                      Assets.svg.verticalEllipsis,
                      colorFilter: ColorFilter.mode(
                        Theme.of(
                          context,
                        ).extension<StackColors>()!.textSubtitle1,
                        BlendMode.srcIn,
                      ),
                      width: 20,
                      height: 20,
                    ),
                    onPressed: widget.onOptionsPressed,
                  ),
              ],
            );
          },
        ),
      ),
    );
  }
}
